-- Live records change only within this transaction; all roll back at the end.
begin;
-- The launch flag turns on only in the rolled-back test transaction.
update public.feature_flags set is_enabled=true,rollout_percent=100 where key='community.enabled';
do $$
declare owner_user public.users; reader public.users; s uuid; c uuid; other_c uuid; base uuid;
  claims_owner text; claims_reader text; idv uuid:=gen_random_uuid(); pending_id uuid:=gen_random_uuid(); msg uuid; keyv uuid:=gen_random_uuid(); p jsonb; output jsonb; rejected boolean;
begin
  select * into owner_user from public.users where username='site_owner';
  select * into reader from public.users where username='denemeuser';
  select id into s from community_v2.servers where owner_id=owner_user.id limit 1;
  if s is null then raise exception 'Sunucu eksik.'; end if;
  claims_owner:=jsonb_build_object('sub',owner_user.auth_user_id,'role','authenticated','session_id',coalesce(owner_user.active_session_id,gen_random_uuid()))::text;
  claims_reader:=jsonb_build_object('sub',reader.auth_user_id,'role','authenticated','session_id',coalesce(reader.active_session_id,gen_random_uuid()))::text;
  perform set_config('request.jwt.claims',claims_owner,true);
  c:=(public.community_v2_write('save_channel',jsonb_build_object('server_id',s,'name','Dosya erişim doğrulaması','is_private',true,'position',999,'role_ids','[]'::jsonb))->>'id')::uuid;
  other_c:=(public.community_v2_write('save_channel',jsonb_build_object('server_id',s,'name','Dosya kanal sınırı','is_private',false,'position',999,'role_ids','[]'::jsonb))->>'id')::uuid;
  p:=jsonb_build_object('id',idv,'channel_id',c,'name','Okuma notları.txt','content_type','text/plain','byte_size',24,'sha256',repeat('a',64));
  perform public.community_v2_media('prepare',p);
  perform public.community_v2_media('prepare',p);
  if (select count(*) from community_v2.attachments where id=idv)<>1 then raise exception 'Yükleme tekrarı çoğaldı.'; end if;
  rejected:=false; begin perform public.community_v2_media('prepare',p||jsonb_build_object('sha256',repeat('b',64))); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Aynı anahtarla farklı dosya kabul edildi.'; end if;
  rejected:=false; begin perform public.community_v2_media_worker('complete',p); exception when insufficient_privilege then rejected:=true; end;
  if not rejected or has_function_privilege('authenticated','public.community_v2_media_worker(text,jsonb)','EXECUTE') then raise exception 'Kullanıcı dosyayı hazır işaretledi.'; end if;
  rejected:=false; begin perform public.community_v2_write('send',jsonb_build_object('channel_id',c,'body','','client_id',keyv,'attachment_ids',array[idv])); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Yarım dosya yayımlandı.'; end if;
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  perform public.community_v2_media_worker('complete',p);
  perform set_config('request.jwt.claims',claims_owner,true);
  update community_v2.members set last_message_at=null where server_id=s and user_id=owner_user.id;
  rejected:=false; begin perform public.community_v2_write('send',jsonb_build_object('channel_id',other_c,'body','','client_id',keyv,'attachment_ids',array[idv])); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Başka kanala dosya taşındı.'; end if;
  rejected:=false; begin perform public.community_v2_write('send',jsonb_build_object('channel_id',c,'body','','client_id',keyv,'attachment_ids',array[idv,idv])); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Tekrarlı ek kabul edildi.'; end if;
  p:=jsonb_build_object('channel_id',c,'body','','client_id',keyv,'attachment_ids',array[idv]);
  msg:=(public.community_v2_write('send',p)->>'id')::uuid;
  if (public.community_v2_write('send',p)->>'id')::uuid<>msg then raise exception 'Yeniden gönderim çoğaldı.'; end if;
  output:=public.community_v2_read('messages',jsonb_build_object('channel_id',c));
  if output->0->'attachments'->0->>'id'<>idv::text then raise exception 'Mesaj eki okunamadı.'; end if;
  perform public.community_v2_media('access',jsonb_build_object('id',idv));
  rejected:=false; begin perform public.community_v2_media('discard',jsonb_build_object('id',idv)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Gönderilmiş ek kaldırıldı.'; end if;
  perform public.community_v2_write('edit_message',jsonb_build_object('channel_id',c,'message_id',msg,'body','Dosyayla paylaşılan okuma notları.','version',1));
  perform public.community_v2_write('edit_message',jsonb_build_object('channel_id',c,'message_id',msg,'body','','version',2));
  insert into community_v2.members(server_id,user_id) values(s,reader.id) on conflict(server_id,user_id) do update set state='active',timeout_until=null,last_message_at=null;
  select id into base from community_v2.roles where server_id=s and is_default;
  update community_v2.roles set permissions=array['channel.view','messages.read','messages.send'] where id=base;
  perform set_config('request.jwt.claims',claims_reader,true);
  rejected:=false; begin perform public.community_v2_media('access',jsonb_build_object('id',idv)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Özel odanın dosyası sızdı.'; end if;
  p:=jsonb_build_object('id',pending_id,'channel_id',other_c,'name','Ekip okuma notları.txt','content_type','text/plain','byte_size',32,'sha256',repeat('c',64));
  rejected:=false; begin perform public.community_v2_media('prepare',p); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Dosya izni olmadan yüklendi.'; end if;
  update community_v2.roles set permissions=array_append(permissions,'attachments.send') where id=base;
  perform public.community_v2_media('prepare',p);
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  perform public.community_v2_media_worker('complete',p);
  perform set_config('request.jwt.claims',claims_owner,true);
  rejected:=false; begin perform public.community_v2_write('send',jsonb_build_object('channel_id',other_c,'body','Okuma dosyası','client_id',gen_random_uuid(),'attachment_ids',array[pending_id])); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Başkasının dosyası yayımlandı.'; end if;
  perform public.community_v2_write('delete_message',jsonb_build_object('channel_id',c,'message_id',msg));
  rejected:=false; begin perform public.community_v2_media('access',jsonb_build_object('id',idv)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Silinen mesajın dosyası hâlâ erişilebilir.'; end if;
  output:=public.community_v2_read('messages',jsonb_build_object('channel_id',c));
  if jsonb_array_length(output->0->'attachments')<>0 then raise exception 'Silinen ek metadatası gösteriliyor.'; end if;
  perform set_config('request.jwt.claims',claims_reader,true);
  update community_v2.roles set permissions=array_remove(permissions,'messages.read') where id=base;
  rejected:=false; begin perform public.community_v2_media('access',jsonb_build_object('id',pending_id)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Yetki kaldırıldıktan sonra dosya okundu.'; end if;
  -- Even after losing permission they can drop their own unsent file.
  perform public.community_v2_media('discard',jsonb_build_object('id',pending_id));
  update community_v2.attachments set expires_at=now()-interval '1 hour' where id in(idv,pending_id);
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  output:=public.community_v2_media_worker('collect','{}');
  if not output @> jsonb_build_array('community/'||idv,'community/'||pending_id) then raise exception 'Silinen dosyalar temizliğe çıkmadı.'; end if;
  perform public.community_v2_media_worker('purged',jsonb_build_object('keys',output));
  if exists(select 1 from community_v2.attachments where id in(idv,pending_id) and state<>'purged') then raise exception 'Temizlik tamamlanmadı.'; end if;
  delete from community_v2.attachments where id=idv;
  if not exists(select 1 from community_v2.media_gc where object_key='community/'||idv) then raise exception 'Fiziksel silme yetim dosya bıraktı.'; end if;
  if has_table_privilege('authenticated','community_v2.attachments','SELECT') or has_function_privilege('anon','public.community_v2_media(text,jsonb)','EXECUTE') then raise exception 'Dosya ACL sızıntısı.'; end if;
end $$;
rollback;
select 'PASS: dosya sahipliği, kanal sınırı, idempotence, hazır olma, rol iptali, silme ve temizlik' as result;
